import java.util.function.IntUnaryOperator;

public class Main {
    // State: each state decides what an event does and which state comes next
    interface Gate { Gate coin(); Gate push(); }
    static class Locked implements Gate {
        public Gate coin() { System.out.println("coin -> unlocked"); return new Unlocked(); }
        public Gate push() { System.out.println("push -> blocked"); return this; }
    }
    static class Unlocked implements Gate {
        public Gate coin() { System.out.println("coin -> already unlocked"); return this; }
        public Gate push() { System.out.println("push -> passes"); return new Locked(); }
    }

    public static void main(String[] args) {
        // Strategy: the caller picks one of several equally valid algorithms
        IntUnaryOperator regular = p -> p;
        IntUnaryOperator member = p -> p * 90 / 100;
        System.out.println("strategy regular -> " + regular.applyAsInt(200));
        System.out.println("strategy member -> " + member.applyAsInt(200));

        Gate gate = new Locked();
        gate = gate.push();
        gate = gate.coin();
        gate = gate.push();
        gate = gate.push();
    }
}

