import java.util.*;

public class Main {
    interface Command { void execute(StringBuilder doc); void undo(StringBuilder doc); }

    // Each command stores only what it needs to reverse itself
    static class Insert implements Command {
        final int pos; final String text;
        Insert(int pos, String text) { this.pos = pos; this.text = text; }
        public void execute(StringBuilder d) { d.insert(pos, text); }
        public void undo(StringBuilder d) { d.delete(pos, pos + text.length()); }
    }

    static StringBuilder doc = new StringBuilder();
    static Deque<Command> undoStack = new ArrayDeque<>();
    static Deque<Command> redoStack = new ArrayDeque<>();

    static void run(Command c) { c.execute(doc); undoStack.push(c); redoStack.clear(); show("run"); }
    static void undo() {
        if (undoStack.isEmpty()) { System.out.println("nothing to undo"); return; }
        Command c = undoStack.pop(); c.undo(doc); redoStack.push(c); show("undo");
    }
    static void redo() {
        if (redoStack.isEmpty()) { System.out.println("nothing to redo"); return; }
        Command c = redoStack.pop(); c.execute(doc); undoStack.push(c); show("redo");
    }
    static void show(String label) { System.out.println(label + " -> '" + doc + "'"); }

    public static void main(String[] args) {
        run(new Insert(0, "Hello"));
        run(new Insert(5, " World"));
        undo();
        undo();
        redo();
        run(new Insert(5, "!"));   // a new edit clears the redo stack
        redo();
    }
}

