import java.util.*;
import java.util.function.IntConsumer;

public class Main {
    static class Subject {
        private final List<Object[]> subs = new ArrayList<>();
        private int nextId = 0;

        // subscribe returns a handle; calling it removes the listener
        Runnable subscribe(IntConsumer l) {
            int id = nextId++;
            subs.add(new Object[]{id, l});
            return () -> subs.removeIf(s -> (int) s[0] == id);
        }

        void publish(int value) {
            // iterate over a snapshot so listeners may unsubscribe while we loop
            for (Object[] s : new ArrayList<>(subs)) {
                try {
                    ((IntConsumer) s[1]).accept(value);
                } catch (RuntimeException e) {
                    // one failing listener must not stop the others
                    System.out.println("listener failed: " + e.getMessage());
                }
            }
        }
    }

    public static void main(String[] args) {
        Subject subject = new Subject();
        subject.subscribe(v -> System.out.println("A got " + v));
        Runnable[] onceHandle = new Runnable[1];
        onceHandle[0] = subject.subscribe(v -> {
            System.out.println("once got " + v);
            onceHandle[0].run();            // unsubscribes itself during notification
        });
        subject.subscribe(v -> { throw new RuntimeException("boom"); });
        subject.subscribe(v -> System.out.println("C got " + v));
        subject.publish(10);
        subject.publish(20);
    }
}

