class Subject:
    def __init__(self):
        self.subs = []
        self.next_id = 0

    def subscribe(self, listener):
        # subscribe returns a handle; calling it removes the listener
        sid = self.next_id
        self.next_id += 1
        self.subs.append((sid, listener))
        def unsubscribe():
            self.subs = [s for s in self.subs if s[0] != sid]
        return unsubscribe

    def publish(self, value):
        # iterate over a snapshot so listeners may unsubscribe while we loop
        for _, listener in list(self.subs):
            try:
                listener(value)
            except Exception as e:
                # one failing listener must not stop the others
                print("listener failed:", e)

