#include <bits/stdc++.h>
using namespace std;

struct Subject {
    vector<pair<int, function<void(int)>>> subs;
    int nextId = 0;

    // subscribe returns a handle; calling it removes the listener
    function<void()> subscribe(function<void(int)> l) {
        int id = nextId++;
        subs.push_back({id, l});
        return [this, id]() {
            subs.erase(remove_if(subs.begin(), subs.end(),
                       [id](auto& s) { return s.first == id; }), subs.end());
        };
    }

    void publish(int value) {
        auto snapshot = subs;   // iterate over a copy so listeners may unsubscribe
        for (auto& s : snapshot) {
            try {
                s.second(value);
            } catch (const exception& e) {
                // one failing listener must not stop the others
                cout << "listener failed: " << e.what() << "\n";
            }
        }
    }
};

int main() {
    Subject subject;
    subject.subscribe([](int v) { cout << "A got " << v << "\n"; });
    function<void()> handle;
    handle = subject.subscribe([&](int v) {
        cout << "once got " << v << "\n";
        handle();                    // unsubscribes itself during notification
    });
    subject.subscribe([](int) { throw runtime_error("boom"); });
    subject.subscribe([](int v) { cout << "C got " << v << "\n"; });
    subject.publish(10);
    subject.publish(20);
}

