using System;
using System.Collections.Generic;

class Program
{
    class Subject
    {
        List<KeyValuePair<int, Action<int>>> subs = new List<KeyValuePair<int, Action<int>>>();
        int nextId = 0;

        // Subscribe returns a handle; calling it removes the listener
        public Action Subscribe(Action<int> l)
        {
            int id = nextId++;
            subs.Add(new KeyValuePair<int, Action<int>>(id, l));
            return () => subs.RemoveAll(s => s.Key == id);
        }

        public void Publish(int value)
        {
            // iterate over a snapshot so listeners may unsubscribe while we loop
            foreach (var s in new List<KeyValuePair<int, Action<int>>>(subs))
            {
                try { s.Value(value); }
                catch (Exception e)
                {
                    // one failing listener must not stop the others
                    Console.WriteLine("listener failed: " + e.Message);
                }
            }
        }
    }

    static void Main()
    {
        Subject subject = new Subject();
        subject.Subscribe(v => Console.WriteLine("A got " + v));
        Action handle = null;
        handle = subject.Subscribe(v =>
        {
            Console.WriteLine("once got " + v);
            handle();                // unsubscribes itself during notification
        });
        subject.Subscribe(v => { throw new Exception("boom"); });
        subject.Subscribe(v => Console.WriteLine("C got " + v));
        subject.Publish(10);
        subject.Publish(20);
    }
}

