import java.util.*;
import java.util.function.Predicate;

public class Main {
    // First-match semantics: the walk stops at the first handler that can deal with it
    static class Approver {
        final String name; final int limit; final Approver next;
        Approver(String name, int limit, Approver next) { this.name = name; this.limit = limit; this.next = next; }
        String handle(int amount) {
            if (amount <= limit || next == null) return name;
            return next.handle(amount);        // pass it along the chain
        }
    }

    public static void main(String[] args) {
        Approver chain = new Approver("TeamLead", 1000,
                new Approver("Manager", 10000, new Approver("Director", Integer.MAX_VALUE, null)));
        for (int amount : new int[]{500, 5000, 50000})
            System.out.println("approve " + amount + " -> " + chain.handle(amount));

        // Pipeline semantics: every handler does its part, any may short-circuit
        String[] names = {"auth", "size"};
        List<Predicate<String[]>> checks = List.of(
                r -> !r[0].isEmpty(),                       // auth: token present
                r -> Integer.parseInt(r[1]) <= 100);        // size: body small enough
        String[][] requests = {{"abc", "5"}, {"", "5"}, {"abc", "500"}};
        for (String[] r : requests) {
            StringBuilder line = new StringBuilder("request token='" + r[0] + "' size=" + r[1] + ":");
            boolean ok = true;
            for (int i = 0; i < checks.size() && ok; i++) {
                if (checks.get(i).test(r)) line.append(" ").append(names[i]).append(" ok");
                else { line.append(" stopped by ").append(names[i]); ok = false; }
            }
            if (ok) line.append(" handled");
            System.out.println(line);
        }
    }
}

