import java.util.function.Function;

public class Main {
    // Template Method: the base class owns the skeleton, subclasses fill in one step
    static abstract class Importer {
        abstract int[] parse(String line);          // the step that varies
        final int run(String line) {                // fixed order of steps
            int sum = 0;
            for (int n : parse(line)) sum += n;
            return sum;
        }
    }
    static class CsvImporter extends Importer {
