    virtual vector<int> parse(const string& line) = 0;   // the step that varies
    int run(const string& line) {                        // fixed order of steps
        auto v = parse(line);
        return accumulate(v.begin(), v.end(), 0);
    }
    virtual ~Importer() {}
};
