import java.util.*;

public class Main {
    static class Node {
        int val; Node left, right;
        Node(int v) { val = v; }
    }
    static Node insert(Node root, int v) {
        if (root == null) return new Node(v);
        if (v < root.val) root.left = insert(root.left, v); else root.right = insert(root.right, v);
        return root;
    }

    // In-order iterator using an explicit stack: O(h) memory, O(1) amortised next()
    static class BstIterator implements Iterator<Integer> {
        private final Deque<Node> stack = new ArrayDeque<>();
        int maxStack = 0;
        BstIterator(Node root) { pushLeft(root); }
        private void pushLeft(Node n) {
            for (; n != null; n = n.left) stack.push(n);   // left spine
            maxStack = Math.max(maxStack, stack.size());
        }
        public boolean hasNext() { return !stack.isEmpty(); }
        public Integer next() {
            if (stack.isEmpty()) throw new NoSuchElementException();
            Node n = stack.pop();       // smallest unvisited value
            pushLeft(n.right);
            return n.val;
        }
    }

    public static void main(String[] args) {
        int[] values = {7, 3, 15, 9, 20};
        Node root = null;
        for (int v : values) root = insert(root, v);
        System.out.println("inserted: " + Arrays.toString(values));
        BstIterator it = new BstIterator(root);
        StringBuilder sb = new StringBuilder();
        while (it.hasNext()) sb.append(it.next()).append(' ');
        System.out.println("in-order: " + sb.toString().trim());
        System.out.println("max stack size: " + it.maxStack);
    }
}

