#include <bits/stdc++.h>
using namespace std;

struct Node {
    int val; Node *left = nullptr, *right = nullptr;
    Node(int v) : val(v) {}
};
Node* insert(Node* root, int v) {
    if (!root) return new Node(v);
    if (v < root->val) root->left = insert(root->left, v); else root->right = insert(root->right, v);
    return root;
}

// In-order iterator using an explicit stack: O(h) memory, O(1) amortised next()
struct BstIterator {
    stack<Node*> st;
    size_t maxStack = 0;
    BstIterator(Node* root) { pushLeft(root); }
    void pushLeft(Node* n) {
        for (; n; n = n->left) st.push(n);   // left spine
        maxStack = max(maxStack, st.size());
    }
    bool hasNext() { return !st.empty(); }
    int next() {
        Node* n = st.top(); st.pop();        // smallest unvisited value
        pushLeft(n->right);
        return n->val;
    }
};

int main() {
    vector<int> values = {7, 3, 15, 9, 20};
    Node* root = nullptr;
    for (int v : values) root = insert(root, v);
    cout << "inserted: [7, 3, 15, 9, 20]\n";
    BstIterator it(root);
    string out;
    while (it.hasNext()) out += to_string(it.next()) + " ";
    out.pop_back();
    cout << "in-order: " << out << "\n";
    cout << "max stack size: " << it.maxStack << "\n";
}

