    }
    static Node Insert(Node root, int v)
    {
        if (root == null) return new Node(v);
        if (v < root.Val) root.Left = Insert(root.Left, v); else root.Right = Insert(root.Right, v);
        return root;
    }

    // In-order iterator using an explicit stack: O(h) memory, O(1) amortised Next()
    class BstIterator
    {
        Stack<Node> stack = new Stack<Node>();
        public int MaxStack = 0;
        public BstIterator(Node root) { PushLeft(root); }
        void PushLeft(Node n)
        {
            for (; n != null; n = n.Left) stack.Push(n);   // left spine
            MaxStack = Math.Max(MaxStack, stack.Count);
        }
        public bool HasNext() { return stack.Count > 0; }
        public int Next()
        {
            Node n = stack.Pop();         // smallest unvisited value
            PushLeft(n.Right);
            return n.Val;
        }
    }

