import java.util.*;
import java.util.function.Consumer;

public class Main {
    // Mediator: users talk only to the room, and the room holds the routing rules
    static class User {
        final String name; boolean muted;
        User(String name, boolean muted) { this.name = name; this.muted = muted; }
    }
    static class Room {
        final List<User> users = new ArrayList<>();
        void send(User from, String msg) {
            for (User u : users)
                if (u != from && !u.muted) System.out.println(u.name + " got '" + msg + "' from " + from.name);
        }
    }

    // Pub/Sub: a broker routes by topic; publishers and subscribers never meet
    static class Broker {
        final Map<String, List<Consumer<String>>> topics = new HashMap<>();
        void subscribe(String topic, Consumer<String> fn) { topics.computeIfAbsent(topic, t -> new ArrayList<>()).add(fn); }
        void publish(String topic, String msg) {
            List<Consumer<String>> subs = topics.getOrDefault(topic, List.of());
            if (subs.isEmpty()) System.out.println("broker: no subscribers for " + topic);
            for (Consumer<String> s : subs) s.accept(msg);
        }
    }

    public static void main(String[] args) {
        Room room = new Room();
        User ann = new User("ann", false), bob = new User("bob", false), cy = new User("cy", true);
        room.users.addAll(List.of(ann, bob, cy));
        room.send(ann, "hi");                       // cy is muted by the room's rule

        Broker broker = new Broker();
        broker.subscribe("orders", m -> System.out.println("sub1 got orders:" + m));
        broker.subscribe("orders", m -> System.out.println("sub2 got orders:" + m));
        broker.publish("orders", "o1");
        broker.publish("audit", "a1");
    }
}

