        {
            List<Action<string>> subs;
            if (!topics.TryGetValue(topic, out subs) || subs.Count == 0)
                Console.WriteLine("broker: no subscribers for " + topic);
            else
                foreach (Action<string> s in subs) s(msg);
        }
    }

