public class Main {
    static String text = "Hello";

    public static void main(String[] args) {
        System.out.println("start: " + text);

        // Command: store the operation and its inverse data (small, but needs a correct inverse)
        String appended = " World";
        text = text + appended;
        System.out.println("append command: " + text);
        text = text.substring(0, text.length() - appended.length());   // inverse: cut it off
        System.out.println("undo command: " + text);

        // Memento: store the state itself (works for any operation, even non-invertible ones)
        String memento = text;                  // snapshot before the change
        text = text.toUpperCase();              // upper-casing destroys the original case
        System.out.println("uppercase: " + text);
        text = memento;                         // restore the snapshot
        System.out.println("memento restore: " + text);

        System.out.println("command stored " + appended.length() + " chars; memento stored " + memento.length() + " chars");
    }
}

