import java.util.*;

public class Main {
    // State: default methods reject everything; each state overrides only its legal events
    static abstract class State {
        abstract String name();
        String pay() { throw new IllegalStateException("cannot pay in " + name()); }
        String ship() { throw new IllegalStateException("cannot ship in " + name()); }
        String cancel() { throw new IllegalStateException("cannot cancel in " + name()); }
    }
    static class New extends State {
        String name() { return "NEW"; }
        String pay() { return "PAID"; }
        String cancel() { return "CANCELLED"; }
    }
    static class Paid extends State {
        String name() { return "PAID"; }
        String ship() { return "SHIPPED"; }
        String cancel() { return "CANCELLED"; }
    }
    static class Shipped extends State { String name() { return "SHIPPED"; } }

    // A fake database row; update() mimics: UPDATE ... WHERE status=? AND version=?
    static String status = "NEW"; static int version = 0;
    static int update(String expStatus, int expVersion, String next) {
        if (!status.equals(expStatus) || version != expVersion) return 0;   // lost the race
        status = next; version++;
        return 1;
    }

    static void handle(String event, String seenStatus, int seenVersion, Map<String, State> states) {
        try {
            State s = states.get(seenStatus);
            String next = event.equals("pay") ? s.pay() : event.equals("ship") ? s.ship() : s.cancel();
            int rows = update(seenStatus, seenVersion, next);
            System.out.println(event + ": " + seenStatus + " -> " + next + ", rows updated " + rows);
        } catch (IllegalStateException e) {
            System.out.println(event + ": illegal, " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        Map<String, State> states = new HashMap<>();
        for (State s : new State[]{new New(), new Paid(), new Shipped()}) states.put(s.name(), s);
        handle("pay", "NEW", 0, states);
        handle("pay", "NEW", 0, states);      // duplicate request with a stale read
        handle("ship", "PAID", 1, states);
        handle("cancel", "SHIPPED", 2, states);
    }
}

