import java.util.*;
import java.util.function.IntUnaryOperator;

public class Main {
    // Before: one growing if/else ladder on a "type" string
    static int ladder(String type, int kg) {
        if (type.equals("standard")) return 5 + kg * 2;
        else if (type.equals("express")) return 15 + kg * 3;
        else if (type.equals("pickup")) return 0;
        return -1;
    }

    // After: Strategy with a registry map; adding a type means adding one entry
    static final Map<String, IntUnaryOperator> COST = new HashMap<>();
    static {
        COST.put("standard", kg -> 5 + kg * 2);
        COST.put("express", kg -> 15 + kg * 3);
        COST.put("pickup", kg -> 0);
    }
    static int viaMap(String type, int kg) {
        IntUnaryOperator f = COST.get(type);
        return f == null ? -1 : f.applyAsInt(kg);
    }

    public static void main(String[] args) {
        // Characterisation check: both versions must give identical answers
        for (String t : new String[]{"standard", "express", "pickup", "drone"})
            System.out.println(t + ": ladder=" + ladder(t, 2) + " map=" + viaMap(t, 2));
    }
}

