import java.util.*;
import java.util.function.Function;

public class Main {
    // A model's tool call is just data: name + arguments
    record Call(String tool, String path, String text) {}

    static Map<String, String> files = new HashMap<>(Map.of("a.txt", "old"));
    static Deque<Runnable> undoStack = new ArrayDeque<>();

    // Registry of known tools; each returns an undo action (the Command's inverse)
    static Map<String, Function<Call, Runnable>> tools = Map.of("write", c -> {
        String previous = files.get(c.path());
        files.put(c.path(), c.text());
        return () -> files.put(c.path(), previous);
    });

    static void execute(Call c) {
        Function<Call, Runnable> tool = tools.get(c.tool());
        if (tool == null) { System.out.println("rejected: unknown tool " + c.tool()); return; }   // validate first
        undoStack.push(tool.apply(c));
        System.out.println("ok " + c.tool() + " " + c.path());
    }

    public static void main(String[] args) {
        execute(new Call("write", "a.txt", "new"));
        execute(new Call("rm_rf", "/", ""));
        System.out.println("a.txt = " + files.get("a.txt"));
        undoStack.pop().run();
        System.out.println("undo write a.txt");
        System.out.println("a.txt = " + files.get("a.txt"));
    }
}

