using System;
using System.Collections.Generic;

class Program
{
    // A model's tool call is just data: name + arguments
    class Call
    {
        public string Tool, Path, Text;
        public Call(string tool, string path, string text) { Tool = tool; Path = path; Text = text; }
    }

    static Dictionary<string, string> files = new Dictionary<string, string> { { "a.txt", "old" } };
    static Stack<Action> undoStack = new Stack<Action>();

    // Registry of known tools; each returns an undo action (the Command's inverse)
    static Dictionary<string, Func<Call, Action>> tools = new Dictionary<string, Func<Call, Action>>
    {
        { "write", c => {
            string previous = files[c.Path];
            files[c.Path] = c.Text;
            return () => { files[c.Path] = previous; };
        } },
    };

    static void Execute(Call c)
    {
        Func<Call, Action> tool;
        if (!tools.TryGetValue(c.Tool, out tool))        // validate first
        {
            Console.WriteLine("rejected: unknown tool " + c.Tool);
            return;
        }
        undoStack.Push(tool(c));
        Console.WriteLine("ok " + c.Tool + " " + c.Path);
    }

    static void Main()
    {
        Execute(new Call("write", "a.txt", "new"));
        Execute(new Call("rm_rf", "/", ""));
        Console.WriteLine("a.txt = " + files["a.txt"]);
        undoStack.Pop()();
        Console.WriteLine("undo write a.txt");
        Console.WriteLine("a.txt = " + files["a.txt"]);
    }
}

