import java.util.concurrent.CopyOnWriteArrayList;

public class Main {
    @FunctionalInterface interface PriceListener { void onPrice(int price); }   // lambdas work as observers

    static class PriceFeed {
        // copy-on-write list: safe to iterate while listeners subscribe or unsubscribe
        private final CopyOnWriteArrayList<PriceListener> listeners = new CopyOnWriteArrayList<>();

        AutoCloseable subscribe(PriceListener l) {
            listeners.add(l);
            return () -> listeners.remove(l);       // closing the handle unsubscribes
        }
        void publish(int price) {
            System.out.println("price=" + price);
            for (PriceListener l : listeners) l.onPrice(price);
        }
    }

    public static void main(String[] args) throws Exception {
        PriceFeed feed = new PriceFeed();
        AutoCloseable logger = feed.subscribe(p -> System.out.println("logger: " + p));
        feed.publish(100);
        try (AutoCloseable alert = feed.subscribe(p -> System.out.println("alert: " + p))) {
            feed.publish(101);
        }                                            // alert is unsubscribed here
        feed.publish(105);
        logger.close();
        feed.publish(110);
    }
}

