#include <bits/stdc++.h>
using namespace std;

struct PriceFeed {
    vector<pair<int, function<void(int)>>> listeners;
    int nextId = 0;

    // a lambda is an observer; the returned handle unsubscribes it by id
    function<void()> subscribe(function<void(int)> l) {
        int id = nextId++;
        listeners.push_back({id, l});
        return [this, id]() {
            listeners.erase(remove_if(listeners.begin(), listeners.end(),
                            [id](auto& p) { return p.first == id; }), listeners.end());
        };
    }
    void publish(int price) {
        cout << "price=" << price << "\n";
        auto copy = listeners;                        // iterate over a copy
        for (auto& p : copy) p.second(price);
    }
};

int main() {
    PriceFeed feed;
    auto logger = feed.subscribe([](int p) { cout << "logger: " << p << "\n"; });
    feed.publish(100);
    auto alert = feed.subscribe([](int p) { cout << "alert: " << p << "\n"; });
    feed.publish(101);
    alert();                                          // alert is unsubscribed here
    feed.publish(105);
    logger();
    feed.publish(110);
}

