using System;
using System.Collections.Generic;

class Program
{
    class Handle : IDisposable
    {
        Action close;
        public Handle(Action close) { this.close = close; }
        public void Dispose() { close(); }              // disposing unsubscribes
    }

    class PriceFeed
    {
        List<Action<int>> listeners = new List<Action<int>>();

        // a lambda is an observer; the returned handle unsubscribes it
        public Handle Subscribe(Action<int> l)
        {
            listeners.Add(l);
            return new Handle(() => listeners.Remove(l));
        }
        public void Publish(int price)
        {
            Console.WriteLine("price=" + price);
            foreach (Action<int> l in new List<Action<int>>(listeners)) l(price);   // iterate over a copy
        }
    }

    static void Main()
    {
        PriceFeed feed = new PriceFeed();
        Handle logger = feed.Subscribe(p => Console.WriteLine("logger: " + p));
        feed.Publish(100);
        using (feed.Subscribe(p => Console.WriteLine("alert: " + p)))
        {
            feed.Publish(101);
        }                                               // alert is unsubscribed here
        feed.Publish(105);
        logger.Dispose();
        feed.Publish(110);
    }
}
